inner="\nfrom pathlib import Path\nimport json,sys,numpy as np,torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,*_=models;cache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\n# Exclude IDs used by the earlier 8,192-ID consensus probe and 4,096-ID\n# diffusion pilots. Other historical source diagnostics may still overlap.\nspecs=(('L_s',2048,1024,2048),('U_s',6144,3072,6144));previous={}\nfor seed,column in ((2026110251,1),(2026110301,2)):\n gen=np.random.default_rng(seed)\n for spec in specs:\n  role=spec[0];available=np.flatnonzero(roles==role);previous.setdefault(role,[]).append(gen.choice(available,size=spec[column],replace=False))\nrng=np.random.default_rng(2026110321);groups=[]\nfor role,_,__,take in specs:\n available=np.flatnonzero(roles==role);available=np.setdiff1d(available,np.unique(np.concatenate(previous[role])),assume_unique=True)\n assert len(available)>=take;groups.append(np.sort(rng.choice(available,size=take,replace=False)))\nfixed=np.concatenate(groups);assert len(fixed)==len(np.unique(fixed))==8192\nsource_rx=rx[fixed];source_day=day[fixed];split=np.full(len(fixed),-1,dtype=np.int64)\nsplit[np.isin(source_rx,[1,3,4])&np.isin(source_day,[1,2])]=0\nsplit[np.isin(source_rx,[4,6])&(source_day==3)]=1\nsplit[(source_rx==8)&(source_day==3)]=2\nassert all(int((split==i).sum())>200 for i in range(3))\nkeep=split==2;fixed=fixed[keep];source_rx=source_rx[keep];source_day=source_day[keep];split=split[keep];assert len(fixed)>200\nviews=('clean','practical_low_suburban','practical_mid_urban','practical_low_urban');namespace='phase1-source-conditional-diffusion-2026110302';data={}\nwith torch.no_grad():\n for view in views:\n  if view=='clean':received=np.asarray(clean[fixed],dtype=np.float32)\n  else:\n   cfgs={snr:Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=snr,boundary='reflect') for snr in (10.,20.,30.)}\n   received=[]\n   for position,j in enumerate(fixed):\n    pid=str(ids[j]);snr=(10.,20.,30.)[stable_seed(2026110312,'diffusion-source-hard-snr',view,pid)%3] if split[position]==0 else 30.;cfg=cfgs[snr]\n    session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110303,session)\n    v=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(v[0]+1j*v[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110302,namespace,view,pid),hw).process(signal)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n   received=np.stack(received)\n  anchors=[];rawp=[];basep=[]\n  for start in range(0,len(fixed),32):\n   x=core.tensor(received[start:start+32],'cpu');a=dura(x);anchors.append(a.cpu())\n   rawp.append(F.softmax(teacher.classify_features(teacher.features(x)),1).cpu())\n   basep.append(F.softmax(teacher.classify_features(teacher.features(a)),1).cpu())\n  data[view]=dict(received=core.tensor(received,'cpu'),anchor=torch.cat(anchors),rawp=np.from_dlpack(torch.cat(rawp).contiguous()),basep=np.from_dlpack(torch.cat(basep).contiguous()))\n  print('SCALED_DIFFUSION_SOURCE_BASELINES_FIXED',view,flush=True)\nprint('ALL_SOURCE_BASELINES_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nclass Block(nn.Module):\n def __init__(self,dilation):\n  super().__init__();self.a=nn.Conv1d(48,48,3,padding=dilation,dilation=dilation);self.b=nn.Conv1d(48,48,3,padding=1)\n def forward(self,x):return x+.2*self.b(F.gelu(self.a(F.gelu(x))))\n\nclass NoiseNet(nn.Module):\n def __init__(self):\n  super().__init__();self.enter=nn.Conv1d(7,48,5,padding=2);self.blocks=nn.Sequential(Block(1),Block(2),Block(4),Block(8),Block(16));self.exit=nn.Conv1d(48,2,3,padding=1)\n def forward(self,z,a,x,sigma):\n  t=sigma[:,None,None].expand(-1,1,z.shape[-1]);return self.exit(self.blocks(self.enter(torch.cat((z,a,x,t),1))))\n\ndef generate(z,a,x):\n for s,next_s in ((.30,.20),(.20,.10),(.10,.05),(.05,0.)):\n  st=torch.full((len(z),),s);noise=net(z,a,x,st);clean_hat=(z-s*noise)/(1-s*s)**.5\n  z=(1-next_s*next_s)**.5*clean_hat+next_s*noise\n return z\nexpected=json.load(sys.stdin);net=NoiseNet();net.load_state_dict({k:torch.tensor(v,dtype=torch.float32) for k,v in expected['model_state'].items()},strict=True);net.eval()\nalpha=expected['selected']['alpha'];outputs={};quality={};reference=core.tensor(np.asarray(clean[fixed],dtype=np.float32),'cpu')\ndef to_complex(x):return torch.complex(x[:,0,:],x[:,1,:])\ndef aligned_mse(signal,target,maxshift=16):\n crop=target[:,maxshift:-maxshift];errors=[]\n for shift in range(-maxshift,maxshift+1):\n  seg=signal[:,maxshift+shift:signal.shape[1]-maxshift+shift];gain=(seg.conj()*crop).sum(1)/seg.abs().square().sum(1).clamp_min(1e-12)\n  errors.append((gain[:,None]*seg-crop).abs().square().mean(1))\n return torch.stack(errors,1).min(1).values\nwith torch.no_grad():\n for view in views:\n  batch_outputs=[];waves=[]\n  for start in range(0,len(fixed),64):\n   a=data[view]['anchor'][start:start+64];x=data[view]['received'][start:start+64]\n   generated=generate((1-.30**2)**.5*a,a,x);relative=((x-a).square().mean((1,2))/(x.square().mean((1,2)).clamp_min(1e-8))).sqrt();gate=(relative/.1).clamp(0,1);wave=a+alpha*gate[:,None,None]*(generated-a)\n   assert torch.isfinite(wave).all();waves.append(wave.cpu());batch_outputs.append(teacher.classify_features(teacher.features(wave)).argmax(1).cpu())\n  outputs[view]=np.from_dlpack(torch.cat(batch_outputs).contiguous());wave=torch.cat(waves);a=data[view]['anchor']\n  before=aligned_mse(to_complex(a),to_complex(reference));after=aligned_mse(to_complex(wave),to_complex(reference))\n  quality[view]=dict(count=len(fixed),aligned_mse_before=float(before.mean()),aligned_mse_after=float(after.mean()),improved=int((after<before).sum()),worsened=int((after>before).sum()))\nprint('ALL_DIFFUSION_SOURCE_OUTPUTS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[fixed]=='L_s';assert np.all(labels[fixed[~labeled]]==-1)\nref=data['clean']['rawp'];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[fixed],teacher_target);results={}\nfor view in views:\n baseline=data[view]['basep'].argmax(1);output=outputs[view];old=baseline==target;new=output==target;lm=valid&labeled\n row=dict(valid_count=int(valid.sum()),L_s_count=int(lm.sum()),U_confident_count=int((valid&~labeled).sum()),baseline=int((valid&old).sum()),student=int((valid&new).sum()),repairs=int((valid&~old&new).sum()),damages=int((valid&old&~new).sum()),L_s_baseline=int((lm&old).sum()),L_s_student=int((lm&new).sum()))\n assert row==expected['heldout'][view],(view,row,expected['heldout'][view]);results[view]=row\nclean_net=int((outputs['clean']==teacher_target).sum()-(data['clean']['basep'].argmax(1)==teacher_target).sum());assert clean_net==expected['heldout_clean_teacher_net']\nprint('SOURCE_SCALED_GUIDED_DIFFUSION_REPLAY '+json.dumps(dict(status='VERIFIED_SOURCE_SCALED_GUIDED_DIFFUSION_REPLAY',heldout_ids=len(fixed),views=results,quality=quality,clean_teacher_net=clean_net,models_refit=0,U_s_labels_read=0,V_reads=0,test_IQ_reads=0,caveat='Router holdout receiver and day are disjoint only for the diffusion model; frozen experts saw source records. IQ fidelity uses paired source reference only for measurement. Simulated data are not validated satellite data.'),ensure_ascii=False),flush=True)\n"
